import { useState } from 'react';
import { useCEProductCustomization } from '../../bitf-customization-engine/useCEProductCustomization';
import { useTranslate } from '../../hooks/useTranslate';

export default function CEAddToCartButton({ storeName, onAddToCartSuccess, language = 'it', buttonText }) {
  const { translate } = useTranslate(language);
  const [isAddingToCart, setIsAddingToCart] = useState(false);
  const [addToCartError, setAddToCartError] = useState(null);
  const { store, resetCustomization } = useCEProductCustomization({
    storeName: storeName,
    watchStoreChanges: false,
  });

  const getListContext = () => {
    const path = window?.location?.pathname || '';
    if (path === '/' || path.includes('/index')) return { listId: 'index', listName: 'HP' };
    if (path.includes('/collections')) return { listId: 'PLP', listName: store?.currentCollectionTitle || 'PLP' };
    if (path.includes('/products')) return { listId: 'PDP', listName: store?.currentProduct?.title || 'PDP' };
    if (path.includes('/cart')) return { listId: 'cart', listName: 'cart' };
    return { listId: 'other', listName: 'other' };
  };

  const fetchCart = async () => {
    const response = await fetch('/cart.js', {
      credentials: 'same-origin',
      headers: {
        Accept: 'application/json',
      },
    });

    if (!response.ok) {
      throw new Error('Failed to fetch cart');
    }

    return response.json();
  };

  /**
   * Add product to cart using Shopify Cart API
   * https://shopify.dev/docs/api/ajax/reference/cart#post--locale-cart-addjs
   */
  const addToCart = async () => {
    if (!store.currentProductVariant) return;
    if (store.validationErrors && store.validationErrors.length > 0) {
      const errorMessage = store.validationErrors[0];
      setAddToCartError(translate('cart.' + errorMessage));
      return;
    }

    setIsAddingToCart(true);
    let hasError = false;

    try {
      // Identifier for grouping customization items
      const customizationGroupId = `${new Date().getTime()}`;

      // Build all items first
      let items = [];

      // Main product
      if (store.currentProductVariant) {
        items.push({
          id: String(store.currentProductVariant.id).split('/').pop(),
          quantity: 1,
          properties: {
            _groupId: customizationGroupId,
            _mainProduct: 'true',
            _customize: 'true',
            _category_2: store?.currentProduct?.cartAttributes?.category2 || '',
            _category_3: store?.currentProduct?.cartAttributes?.category3 || '',
            _list_id: getListContext().listId,
            _list_name: getListContext().listName,
          },
        });
      }

      // Customization Product
      if (store.currentCustomizationProduct?.selectedOrFirstAvailableVariant?.id) {
        items.push({
          id: String(store.currentCustomizationProduct.selectedOrFirstAvailableVariant.id).split('/').pop(),
          quantity: 1,
          properties: {
            _groupId: customizationGroupId,
            _customizationProduct: store.currentCustomizationType,
            _customizationFont: store.currentFont?.handle,
            _customizationName: store.customizationName,
            _customizationNumber: store.customizationNumber,
            Name: store.customizationName,
            Number: store.customizationNumber,
            _category_2: store?.currentCustomizationProduct?.cartAttributes?.category2 || '',
            _category_3: store?.currentCustomizationProduct?.cartAttributes?.category3 || '',
            _list_id: getListContext().listId,
            _list_name: getListContext().listName,
          },
        });
      }

      // Addon Products
      if (store.currentAddOns?.length > 0) {
        const validAddOns = store.currentAddOns
          .filter((addOn) => addOn.selectedOrFirstAvailableVariant?.id)
          .map((addOn) => ({
            id: String(addOn.selectedOrFirstAvailableVariant.id).split('/').pop(),
            quantity: 1,
            properties: {
              _groupId: customizationGroupId,
              _customizationProductType: 'add_on',
              _category_2: addOn?.cartAttributes?.category2 || '',
              _category_3: addOn?.cartAttributes?.category3 || '',
              _list_id: getListContext().listId,
              _list_name: getListContext().listName,
            },
          }));
        items.push(...validAddOns);
      }

      // Calculate the IDs of all products in the group
      const allProductIds = items.map((item) => item.id);

      // Add the _customizationProducts property to each item
      items = items.map((item) => ({
        ...item,
        properties: {
          ...item.properties,
          _customizationProducts: allProductIds.filter((id) => id !== item.id).join(','),
        },
      }));

      let formData = {
        items: items,
      };

      const response = await fetch(window.Shopify.routes.root + 'cart/add.js', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        const errorData = await response.json();
        console.error('Add to cart failed:', errorData);
        throw new Error(errorData.message || errorData.description || 'Failed to add to cart');
      }

      try {
        if (window?.free_samples_enabled != false) {
          const latestCart = await fetchCart();

          document.dispatchEvent(
            new CustomEvent('free-product:sync', {
              detail: {
                cart: latestCart,
                options: {
                  forceRefresh: true,
                },
              },
            }),
          );
        } else {
          document.dispatchEvent(new CustomEvent('cart:build', { bubbles: true }));
          document.dispatchEvent(new CustomEvent('cart:refresh', { bubbles: true }));
        }
      } catch (error) {
        console.error('[FreeProduct] ensure failed after add-to-cart:', error);
      }

      // Apri il cart drawer
      setTimeout(() => {
        const cartDrawer = document.querySelector('cart-drawer');
        if (cartDrawer && typeof cartDrawer.show === 'function') {
          cartDrawer.show();
        } else {
          // Alternativa: cerca un pulsante del cart
          const cartButton =
            document.querySelector('[data-action="open-drawer"][data-drawer-id="cart-drawer"]') ||
            document.querySelector('.header__cart-button') ||
            document.querySelector('[aria-controls="cart-drawer"]');
          if (cartButton) {
            cartButton.click();
          } else {
            // Ultima alternativa: mostra il drawer direttamente
            const drawer = document.querySelector('#cart-drawer');
            if (drawer && drawer.show) {
              drawer.show();
            }
          }
        }
      }, 400);

      // Call success callback if provided (for quick-buy reset)
      if (onAddToCartSuccess && typeof onAddToCartSuccess === 'function') {
        onAddToCartSuccess();
      } else {
        resetCustomization();
      }

      // Optional: Show success message or redirect
      // window.location.href = window.Shopify.routes.root + 'cart';
    } catch (error) {
      hasError = true;
      const errorMessage = error.message || translate('cart.error_generic');
      setAddToCartError(errorMessage);
    } finally {
      setIsAddingToCart(false);

      if (!hasError) {
        const closeButton = document.querySelector('dialog-close-button button');
        if (closeButton) {
          closeButton.click();
        }
      }
    }
  };

  return store?.currentProductVariant?.available || store.currentProductVariant?.availableForSale ? (
    <div className="text-center w-full">
      <button
        className="ASRomaFont Small ExtraBold asroma-button button--solid w-full button-primary Uppercase"
        onClick={addToCart}
        disabled={!store.currentProductVariant || store.isLoadingCustomization !== false || isAddingToCart}
      >
        {isAddingToCart ? translate('cart.adding') : buttonText ? buttonText : translate('cart.add_to_cart')}
      </button>
      {addToCartError && <div className="product-customization__error-message">{addToCartError}</div>}
    </div>
  ) : (
    <div className="text-center w-full">
      <button
        className="ASRomaFont Small ExtraBold asroma-button button--solid w-full Uppercase button-primary"
        disabled
      >
        {buttonText ? buttonText : translate('cart.sold_out')}
      </button>
    </div>
  );
}
